public static void main(String[] args) {
    AReader sc = new AReader();
    int n = sc.nextInt(), m = sc.nextInt();
    int[] x = new int[m + 1];
    long[] d = new long[n + 2];
    for (int i = 1; i <= m; i++) {
        x[i] = sc.nextInt();
    }
    long ans = 0;
    for (int i = 1; i <= m - 1; i++) {
        int from = x[i], to = x[i + 1];
        if (from > to) {
            int temp = from;
            from = to;
            to = temp;
        }
        int directDistance = to - from;
        int circularDistance = n - to + from;
        if (directDistance <= circularDistance) {
            d[from] += 1;
            d[to] -= 1;
            ans += directDistance;
        } else {
            d[1] += 1;
            d[from] -= 1;
            d[to] += 1;
            d[n + 1] -= 1;
            ans += circularDistance;
        }
    }
    long mn = Long.MAX_VALUE;
    for (int i = 1; i <= n; i++) {
        d[i] += d[i - 1];
        mn = Math.min(mn, d[i]);
    }
    System.out.println(ans + mn);
}
